INSERT INTO RULE_LOG (
LOG_TITLE
, LOG_START_TIME
, LOG_END_TIME
, TIME_GAP
, LOG_REQUEST
, LOG_RESPONSE
, RULEALIAS_NM
, LOG_NO
, RULE_ID
, RULE_VERNO
, INSPECTION_YN
, RES_CODE
) VALUES (
#{logTitle}
, #{logStartTime}
, #{logEndTime}
, #{timeGap}
, #{logRequest}
, #{logResponse}
, #{ruleAliasNm}
, nextval('rule_log_seq')
, #{ruleId}
, #{ruleVerNo}
, #{inspectionYn}
, #{resCode}
)
